const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const Item = models.DirectorateMenuItem;
const uri = process.env.MONGODB_URI || process.env.MONGO_URI || process.env.MONGODB_URL || process.env.DATABASE_URL;
await mongoose.connect(uri);

const items = await Item.find({ directorateKey: 'nss' }).sort({ sortOrder: 1 });
console.log('NSS menu items:');
for (const i of items) console.log(`  [${i.menuKey}] "${i.label}"  parent=${i.parentKey || '-'}  type=${i.type}  bodyLen=${(i.body || '').length}`);

const plan = [];
let ok = true;
for (const [key, body] of Object.entries(DATA)) {
  const hit = items.filter((i) => norm(i.label) === norm(key) || norm(i.menuKey) === norm(key));
  if (hit.length !== 1) { ok = false; console.log(`!! "${key}": found ${hit.length} matching menu items`); continue; }
  plan.push([hit[0], body]);
  console.log(`OK  "${key}" -> [${hit[0].menuKey}]  (${body.length} chars)`);
}
if (!APPLY) { console.log('\nDRY RUN - nothing saved.'); await mongoose.disconnect(); process.exit(0); }
if (!ok) { console.log('\nRefusing to apply: fix the unmatched items first.'); await mongoose.disconnect(); process.exit(1); }
for (const [it, body] of plan) { it.type = 'page'; it.body = body; it.isActive = true; await it.save(); }
console.log(`\nSaved ${plan.length} pages.`);
await mongoose.disconnect();
